package com.repairconnect.controller;
import com.repairconnect.entity.*; import com.repairconnect.repository.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/reviews") public class ReviewController {final ReviewRepository reviews;final BookingRepository bookings;final CustomerRepository customers;final ProviderRepository providers; ReviewController(ReviewRepository r,BookingRepository b,CustomerRepository c,ProviderRepository p){reviews=r;bookings=b;customers=c;providers=p;} record Request(@NotNull Long bookingId,@Min(1)@Max(5) int rating,String comment){} @PostMapping @PreAuthorize("hasRole('CUSTOMER')") Review add(@Valid @RequestBody Request r,org.springframework.security.core.Authentication a){var b=bookings.findById(r.bookingId()).orElseThrow();if(b.getStatus()!=BookingStatus.COMPLETED||!b.getCustomer().getUser().getEmail().equals(a.getName())||reviews.existsByBookingId(b.getId()))throw new RuntimeException("Review is not allowed");var review=reviews.save(new Review(b,customers.findByUserEmail(a.getName()).orElseThrow(),b.getProvider(),r.rating(),r.comment()));var p=b.getProvider();var allReviews=reviews.findByProviderIdOrderByCreatedAtDesc(p.getId());double avg=allReviews.stream().mapToInt(Review::getRating).average().orElse(0.0);p.setTotalReviews(allReviews.size());p.setAverageRating(avg);providers.save(p);return review;} @GetMapping("/provider/{providerId}") List<Review> byProvider(@PathVariable Long providerId){return reviews.findByProviderIdOrderByCreatedAtDesc(providerId);} }